import{_ as o,o as a,c as d,a1 as s}from"./chunks/framework.DceXOx8u.js";const g=JSON.parse('{"title":"Seguridad","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://andresayac.github.io/botmesh/es/guide/seguridad"}],["meta",{"property":"og:url","content":"https://andresayac.github.io/botmesh/es/guide/seguridad"}]]},"headers":[],"relativePath":"es/guide/seguridad.md","filePath":"es/guide/seguridad.md"}'),r={name:"es/guide/seguridad.md"};function c(t,e,n,i,l,u){return a(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="seguridad" tabindex="-1">Seguridad <a class="header-anchor" href="#seguridad" aria-label="Permalink to &quot;Seguridad&quot;">​</a></h1><p>Qué tienes que configurar tú, qué verifica el framework por ti en cada superficie no confiable y qué riesgos quedan. Para reportar una vulnerabilidad, sigue <a href="https://github.com/andresayac/botmesh/blob/main/SECURITY.md" target="_blank" rel="noreferrer"><code>SECURITY.md</code></a>. Para saber de quién protege el framework y frente a qué, mira el <a href="./modelo-amenazas">Modelo de amenazas</a>.</p><h2 id="lista-de-comprobacion-para-produccion" tabindex="-1">Lista de comprobación para producción <a class="header-anchor" href="#lista-de-comprobacion-para-produccion" aria-label="Permalink to &quot;Lista de comprobación para producción&quot;">​</a></h2><p>Lo que queda en tus manos. El resto de la página explica cada punto.</p><ul><li><strong>Secretos fuera del código.</strong> Los tokens de los providers, las claves de API, los app secrets y los secretos de webhook salen del entorno o de un gestor de secretos. La carpeta <code>sessions/</code> (claves de WhatsApp), <code>.env</code>, los archivos del store y <code>*.qr.png</code> nunca se commitean ni se meten en una imagen.</li><li><strong>Los webhooks verifican al remitente.</strong> Configura el secreto del canal (<code>appSecret</code> y <code>verifyToken</code> para la Cloud API, <code>webhookSecret</code> para Telegram, el auth token para Twilio…). Todos los providers se niegan a arrancar sin él salvo que pongas <code>allowUnsignedWebhooks: true</code>: nunca lo pongas en producción. Ver <a href="#autenticacion-de-webhooks">Autenticación de webhooks</a>.</li><li><strong>HTTPS en todas partes.</strong> La mayoría de plataformas no firman una marca de tiempo, así que una petición capturada puede repetirse; TLS impide la captura.</li><li><strong>Body crudo para las firmas.</strong> Nada de parsers de JSON delante de las rutas de webhooks: las firmas se comprueban sobre los bytes recibidos (<a href="./servidor">Servidor de webhooks</a>).</li><li><strong>Nada de texto del usuario como origen de media.</strong> Un string o <code>{ path }</code> como media se lee del disco local, y en Baileys también un <code>{ url }</code> que no sea <code>http</code>. Pasa URLs <code>https</code> que hayas comprobado tú o Buffers construidos con datos de confianza: solo Baileys descarga la media remota con <code>@botmesh/http</code>; los demás transportes entregan el enlace a su servidor o a la plataforma (ver <a href="#riesgos-residuales">Riesgos residuales</a>).</li><li><strong>Los datos personales no llegan a logs ni trazas.</strong> Deja <code>logIds: &#39;hash&#39;</code> (el valor por defecto) y <code>telemetry.ids: &#39;hash&#39;</code> con un <code>idKey</code> secreto; no actives <code>telemetry.errorMessages</code>.</li><li><strong>Protege el store y los journals</strong> como los mensajes que contienen: permisos de archivo restringidos, copias cifradas, Redis con autenticación y TLS en redes no confiables.</li><li><strong>Los endpoints de operación son privados.</strong> Salud, métricas y cualquier API de administración escuchan en una interfaz privada o detrás de autenticación.</li><li><strong>Atiende las solicitudes de borrado</strong> con <code>bot.deleteSubject(userId)</code> (y <code>bot.exportSubject(userId)</code> para las de acceso).</li></ul><h2 id="auditoria-de-seguridad-2026-10" tabindex="-1">Auditoría de seguridad (2026-10) <a class="header-anchor" href="#auditoria-de-seguridad-2026-10" aria-label="Permalink to &quot;Auditoría de seguridad (2026-10)&quot;">​</a></h2><p>El resto de la página es el resultado de la auditoría de octubre de 2026 de las superficies nuevas (ingress de webhooks, API REST del manager, canales y plugins nuevos). La mayoría de los paquetes auditados son públicos desde la beta; <code>manager</code> y <code>tiktok</code> siguen siendo privados. Los publicados se listan en <a href="./produccion#que-paquetes-estan-publicados">Pasar a producción</a>.</p><p><strong>Alcance:</strong> <code>@botmesh/server</code>, <code>twilio</code>, <code>gohighlevel</code>, <code>gupshup</code>, <code>evolution</code>, <code>wppconnect</code>, <code>email</code>, <code>tiktok</code>, <code>chatwoot</code>, <code>voice</code>, <code>rag</code>, <code>manager</code> (REST <code>/v1</code> y el antiguo <code>createManagerApi</code>), <code>dialogflow</code>, <code>moderation</code>, los webhooks de <code>meta</code>/<code>messenger</code>/<code>instagram</code> (<code>@botmesh/graph-core</code>) y <code>telegram</code>, más el cliente HTTP compartido <code>@botmesh/http</code>.</p><p>Cada problema corregido en la auditoría tiene su test de regresión (busca <code>security-audit</code> en los tests del paquete).</p><h3 id="autenticacion-de-webhooks" tabindex="-1">Autenticación de webhooks <a class="header-anchor" href="#autenticacion-de-webhooks" aria-label="Permalink to &quot;Autenticación de webhooks&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Canal</th><th>Mecanismo</th><th>Bytes crudos</th><th>Tiempo constante</th><th>Ventana anti-replay</th></tr></thead><tbody><tr><td>Meta (Cloud API, Messenger, Instagram)</td><td>HMAC-SHA256 <code>X-Hub-Signature-256</code> con <code>appSecret</code>; handshake <code>GET</code> con <code>verifyToken</code></td><td>sí (un body ya parseado se rechaza)</td><td>sí (también el token del handshake)</td><td>Meta no firma un timestamp: dedupe por id de mensaje</td></tr><tr><td>Telegram</td><td><code>X-Telegram-Bot-Api-Secret-Token</code> (<code>webhookSecret</code>)</td><td>n/a (secreto compartido)</td><td>sí</td><td>la plataforma no la ofrece</td></tr><tr><td>Twilio</td><td>HMAC-SHA1 <code>X-Twilio-Signature</code> sobre la URL exacta + parámetros ordenados; bodies JSON vía <code>bodySHA256</code></td><td>sí</td><td>sí</td><td>la plataforma no la ofrece</td></tr><tr><td>TikTok</td><td><code>TikTok-Signature: t=…,s=…</code> HMAC-SHA256 sobre <code>t.rawBody</code></td><td>sí</td><td>sí</td><td><strong>sí</strong>, ±300 s (<code>signatureToleranceSec</code>)</td></tr><tr><td>HighLevel</td><td>Ed25519 <code>X-GHL-Signature</code> (RSA heredado <code>X-WH-Signature</code> solo si configuras su clave)</td><td>sí</td><td>n/a (verificación de firma)</td><td>no se aplica; ver riesgos residuales</td></tr><tr><td>Gupshup, WPPConnect</td><td>token compartido en la URL del callback o en una cabecera (no firman)</td><td>n/a</td><td>sí</td><td>ninguna</td></tr><tr><td>Evolution</td><td>secreto en cabecera o JWT HS256 (<code>exp</code> obligatorio, ±30 s de desfase)</td><td>n/a</td><td>sí</td><td>el <code>exp</code> del JWT</td></tr><tr><td>Chatwoot</td><td>token compartido y/o HMAC-SHA256 (<code>x-chatwoot-signature</code> sobre <code>x-chatwoot-timestamp</code> + body, ±300 s)</td><td>sí</td><td>sí</td><td><strong>sí</strong>, ±300 s; la forma sin timestamp exige <code>webhookAllowUntimedSignature</code></td></tr></tbody></table><p>Ningún provider arranca sin credenciales salvo que pongas <code>allowUnsignedWebhooks: true</code> (o <code>insecureNoWebhookAuth</code> en Chatwoot), y en ese caso registra un aviso. El core deduplica los ids de entrada (<code>chatId</code> + id de mensaje), lo que también absorbe la repetición de un mensaje ya visto mientras siga en la ventana de dedupe.</p><h3 id="verificado" tabindex="-1">Verificado <a class="header-anchor" href="#verificado" aria-label="Permalink to &quot;Verificado&quot;">​</a></h3><ul><li><strong>Firmas sobre el body crudo.</strong> Las firmas se calculan sobre los bytes recibidos, nunca sobre JSON re-serializado. <code>@botmesh/server</code> lee el body crudo él mismo y responde <code>500</code> si un body parser lo consumió antes.</li><li><strong>Límites del ingress</strong> (<code>@botmesh/server</code>): tamaño del body (<code>413</code>, por <code>Content-Length</code> y durante la lectura), timeouts de body e ingest (<code>408</code>/<code>503</code>), tope de concurrencia (<code>503</code> + <code>Retry-After</code>), cabeceras de respuesta a salvo de inyección (se rechazan CR/LF/NUL) y logs solo con metadatos (sin bodies ni mensajes de error que puedan citar un body).</li><li><strong>SSRF saliente.</strong> Todo fetch a una URL que llega de un webhook o de un usuario (descargas de media, adjuntos, STT/TTS, embeddings, Dialogflow) pasa por <code>secureFetch</code>: solo HTTPS por defecto, sin credenciales en la URL, respuestas DNS comprobadas contra rangos privados y socket fijado a la IP comprobada (sin DNS rebinding), cada redirección revalidada, timeouts y límites de tamaño. Los rechazos son un <code>SecureHttpError</code> cuyo <code>code</code> dice el motivo: <code>INVALID_URL</code>, <code>INVALID_OPTIONS</code>, <code>UNSAFE_URL</code>, <code>UNSAFE_HOST</code>, <code>TIMEOUT</code>, <code>RESPONSE_TOO_LARGE</code>, <code>TOO_MANY_REDIRECTS</code> o <code>HTTP_STATUS</code> (un status no 2xx en <code>fetchBuffer</code>, con el código en <code>error.status</code>).</li><li><strong>REST <code>/v1</code> del manager.</strong> Tokens obligatorios (≥ 16 caracteres, comparados como digests SHA-256 sin salida temprana), scopes por ruta, aislamiento por tenant (los bots de otro tenant responden <code>404</code>), rate limiting por token bucket, límite de <code>1 MiB</code> de JSON, <code>415</code> si no es JSON, campos en lista blanca, strings con longitud máxima, secretos redactados en la configuración devuelta y mensajes <code>500</code> genéricos. Los ids de bot y de tenant se limitan a <code>[A-Za-z0-9][A-Za-z0-9_.-]{0,63}</code> (sin <code>..</code>) antes de usarse como nombres de archivo.</li><li><strong>Expresiones de flujos JSON.</strong> Un parser descendente recursivo: sin <code>eval</code>/<code>Function</code>, sin regex, solo funciones en lista blanca, <code>__proto__</code>/<code>prototype</code>/<code>constructor</code> rechazados, solo rutas de propiedades propias, como mucho 1000 caracteres / 256 tokens / profundidad 32. Las plantillas (<code>{{ ruta }}</code>) solo resuelven rutas.</li><li><strong>Email.</strong> Las <code>headers</code> nativas deben ser de una línea y no pueden pisar las del provider (<code>From</code>, <code>To</code>, <code>Message-ID</code>, protección anti-bucles...); los adjuntos nativos deben estar en memoria (nada de <code>path</code>/<code>href</code> que nodemailer leería o descargaría por su cuenta).</li><li><strong>Loaders de RAG</strong>: solo leen rutas que da el operador, se saltan symlinks y archivos ocultos al recorrer directorios y limitan cada archivo (20 MiB).</li><li><strong>Logs.</strong> Revisadas todas las llamadas <code>logger.*</code> de los paquetes auditados: sin tokens, payloads de QR, cuerpos de mensaje ni direcciones; los errores se registran por clase o por el motivo que reporta el provider. Las líneas del propio core llevan los ids de chat y de remitente según <code>BotConfig.logIds</code>: hasheados por defecto (HMAC de 16 caracteres, el mismo hash que los spans de las trazas; unos spans con <code>telemetry.ids: &#39;raw&#39;</code> no vuelven crudos los logs), <code>&#39;raw&#39;</code> para depurar en local y <code>&#39;omit&#39;</code> para quitarlos.</li></ul><h3 id="corregido-en-la-auditoria" tabindex="-1">Corregido en la auditoría <a class="header-anchor" href="#corregido-en-la-auditoria" aria-label="Permalink to &quot;Corregido en la auditoría&quot;">​</a></h3><ul><li><strong><code>@botmesh/http</code>: bypass de SSRF por IPv6.</strong> <code>isPrivateAddress</code> no entendía las IPv6 que embeben una IPv4: <code>https://[::ffff:7f00:1]/</code> (la forma a la que <code>URL</code> normaliza <code>::ffff:127.0.0.1</code>), <code>::127.0.0.1</code>, NAT64 (<code>64:ff9b::/96</code>), 6to4 (<code>2002::/16</code>) y Teredo llegaban a direcciones internas. Ahora expande la IPv6 y juzga la IPv4 embebida; un literal que no se puede parsear se bloquea.</li><li><strong><code>@botmesh/http</code>: redirecciones.</strong> Al cambiar de origen también se quitan las cabeceras con pinta de credencial (<code>apikey</code>, <code>x-api-key</code>, <code>xi-api-key</code>, <code>x-auth-token</code>...), no solo <code>Authorization</code>/<code>Cookie</code>; un <code>303</code> (y un <code>301</code>/<code>302</code> tras un <code>POST</code>) sigue como <code>GET</code> sin body, como hace <code>fetch</code>.</li><li><strong><code>@botmesh/manager</code>: SSRF vía <code>send</code>.</strong> <code>POST /v1/bots/{id}/send</code> aceptaba cualquier URL <code>https</code> de media, y transportes como Baileys descargan los <code>{ url }</code> por su cuenta (fuera de <code>secureFetch</code>). Ahora se rechazan con <code>400</code> los hosts que son o resuelven a direcciones internas (<code>allowPrivateMediaHosts: true</code> para desactivarlo, <code>mediaHostResolver</code> para tests).</li><li><strong><code>@botmesh/baileys</code>: SSRF por redirecciones.</strong> Baileys descargaba los <code>{ url }</code> con <code>fetch</code> sin más, que sigue las redirecciones sin comprobarlas, así que una URL pública que respondía <code>302</code> hacia <code>http://169.254.169.254/…</code> se saltaba la comprobación de host de la API REST. Ahora el provider descarga la media remota él mismo con <code>@botmesh/http</code> (cada salto revalidado, socket fijado a la dirección comprobada, límites de 64 MiB y 60 s) y le pasa un Buffer a Baileys. Se ajusta con <code>remoteMedia</code> (<code>maxBytes</code>, <code>timeoutMs</code>, <code>allowHttp</code>); <code>remoteMedia.allowPrivateHosts: true</code> recupera el paso directo anterior para media servida desde tu propia red.</li><li><strong><code>@botmesh/manager</code>: fuga de errores.</strong> El antiguo <code>createManagerApi</code> devolvía el mensaje del error en los <code>500</code>; ahora responde <code>&quot;start failed&quot;</code>/<code>&quot;stop failed&quot;</code> y entrega el error a <code>onError</code>.</li><li><strong><code>@botmesh/graph-core</code>: verify token.</strong> El handshake <code>GET</code> comparaba el token con <code>===</code> y aceptaba un token configurado vacío; ahora es en tiempo constante, no vacío y solo strings.</li><li><strong><code>@botmesh/email</code>: inyección de cabeceras.</strong> Asuntos y nombres visibles decodificados de RFC 2047 podían meter CR/LF en el <code>Subject</code>/<code>To</code> de la respuesta; se reducen a una línea. Los <code>cc</code>/<code>bcc</code> nativos deben ser direcciones simples.</li><li><strong><code>@botmesh/gohighlevel</code>: replay entre locations.</strong> HighLevel firma los webhooks de todas las apps con una sola clave de plataforma, así que un body firmado para otra location también verificaba aquí; los eventos sin <code>locationId</code> (o con otro) se ignoran.</li><li><strong><code>@botmesh/chatwoot</code>: adjuntos de agentes.</strong> Solo se reenvían URLs <code>http(s)</code> absolutas (Baileys lee de disco cualquier otro <code>{ url }</code>), los nombres de archivo pierden los separadores de ruta y un <code>%</code> mal formado ya no descarta el mensaje entero.</li><li><strong><code>@botmesh/moderation</code>: escaneo cuadrático de enlaces.</strong> <code>findLinks</code> comparaba cada invitación suelta con cada enlace (≈2,5 s con un mensaje de 200 KB); ahora es lineal.</li></ul><h3 id="riesgos-residuales" tabindex="-1">Riesgos residuales <a class="header-anchor" href="#riesgos-residuales" aria-label="Permalink to &quot;Riesgos residuales&quot;">​</a></h3><ul><li><strong>Sin ventana anti-replay de la plataforma</strong> en Meta, Telegram, Twilio, HighLevel, Gupshup y WPPConnect: no firman un timestamp (o el de HighLevel no se aplica, porque sus reintentos pueden reutilizarlo). Una petición válida capturada se puede repetir; el dedupe por id del core solo cubre su ventana en memoria. Sirve los webhooks por HTTPS para que no se puedan capturar.</li><li><strong>Tokens en la URL</strong> (Gupshup, WPPConnect, Chatwoot <code>?token=</code>) acaban en los logs del proxy inverso y de acceso. Usa la cabecera cuando la plataforma lo permita y limpia los query strings de tus logs.</li><li><strong>Reconstrucción de la URL en Twilio.</strong> Sin <code>webhookUrl</code>, la URL firmada se reconstruye desde <code>X-Forwarded-Host</code>/<code>Host</code>. Pon <code>webhookUrl</code> (o usa <code>ingestRequest</code> con la URL exacta) detrás de proxies que no controlas.</li><li><strong>Regex escritas por el operador.</strong> Los filtros de palabras y los patrones de invitación de <code>moderation</code> aceptan <code>RegExp</code> y se ejecutan con cada mensaje: un patrón con backtracking catastrófico es un ReDoS. Usa strings, o solo patrones lineales.</li><li><strong>Las fuentes de media string son rutas locales.</strong> En <code>ctx.send</code>/<code>bot.send</code> una fuente string o <code>{ path }</code> se lee de disco, y Baileys también lee de disco un <code>{ url }</code> que no sea <code>http</code>. Nunca pases texto del usuario como fuente de media; la API REST y Chatwoot ya lo limitan a URLs <code>http(s)</code>.</li><li><strong>Transportes que descargan por su cuenta.</strong> Evolution y WPPConnect pasan los <code>{ url }</code> a su propio servidor, que los descarga (y sigue redirecciones) desde su red; Cloud API, Messenger, Instagram, Twilio, Gupshup y HighLevel le dan el enlace a la plataforma. La API REST comprueba el primer host, pero una redirección la resuelve ese otro servidor, fuera de <code>secureFetch</code>. Despliega esos servidores donde un destino interno no sea alcanzable, o envía Buffers. Baileys está cubierto (descarga con <code>@botmesh/http</code>) salvo que pongas <code>remoteMedia.allowPrivateHosts: true</code>.</li><li><strong>El estado en memoria crece con los contactos</strong>: los mapas de identidad LID/PN (Evolution, WPPConnect, Baileys), los contadores de avisos de moderación y la lista de supresión de email no tienen tope. El resto de mapas por chat están acotados.</li><li><strong>Texto de error de terceros.</strong> Los errores de STT/TTS/Dialogflow incluyen el mensaje corto del proveedor (≤ 200 caracteres); los proveedores enmascaran las claves, pero es texto de terceros.</li><li><strong>El antiguo <code>createManagerApi</code></strong> no tiene autenticación salvo que pases <code>auth</code> (avisa una vez). Mejor <code>createRestApi</code>.</li><li><strong>Nombres de dispositivo de Windows.</strong> Ids de bot como <code>con</code> o <code>nul</code> pasan el patrón; evítalos si persistes bots en Windows.</li></ul>',18)])])}const m=o(r,[["render",c]]);export{g as __pageData,m as default};
